//=================================================================
//      Default Values for Each PLC Scan Cycle
//=================================================================

{region 'State Update'}
    eCurrentState   := eNextState;   
{endregion}

{region 'Default Outputs'}
    MVBreaker.DQ.xCmdOpen          := FALSE;
    MVBreaker.DQ.xCmdClose         := FALSE;
{endregion}

{region 'Default Requests'}
    xOpenRequestPulse   := FALSE;
    xCloseRequestPulse  := FALSE;
{endregion}

(*===================================================================================
                                Timers Control
=====================================================================================*)

{region 'Request Edge Detection'}
(*-----------------------------------------------------------------------------------
    Monitor requests continuously so a request held while control is unavailable
    cannot unexpectedly execute when control is restored.
                ALL AUTO & HMI REQUEST ARE RISING_EDGE DETECTED
-------------------------------------------------------------------------------------*)
    rtAutoOpenRequest(
        CLK := xAutoOpenRequest
    );
    rtAutoCloseRequest(
        CLK := xAutoCloseRequest
    );
    rtHMIOpenRequest(
        CLK := MVBreaker.HMI.xHMIOpenRequest
    );
    rtHMICloseRequest(
        CLK := MVBreaker.HMI.xHMICloseRequest
    );
    rtHMIResetRequest(
        CLK := MVBreaker.HMI.xHMIResetRequest
    );
    rtHMIAlarmAcknowledge(
        CLK := MVBreaker.HMI.xHMIAlarmAcknowledge
    );
{endregion}


{region 'Feedback Debounce'}
(*-----------------------------------------------------------------------------------
    Accept a feedback change only after it has remained stable for the
    configured debounce time.
-------------------------------------------------------------------------------------*)
    tonOpenFeedbackDebounce(
        IN := MVBreaker.DI.xOpened <> xOpenFeedbackDebounced,
        PT := tFeedbackDebounce
    );
    IF tonOpenFeedbackDebounce.Q THEN
        xOpenFeedbackDebounced := MVBreaker.DI.xOpened;
    END_IF;

    tonCloseFeedbackDebounce(
        IN := MVBreaker.DI.xClosed <> xCloseFeedbackDebounced,
        PT := tFeedbackDebounce
    );
    IF tonCloseFeedbackDebounce.Q THEN
        xCloseFeedbackDebounced := MVBreaker.DI.xClosed;
    END_IF;
{endregion}


{region 'Feedback Fault Delay'}
(*-----------------------------------------------------------------------------------
    Exactly one breaker-position feedback must normally be active.

    Both active or both inactive is tolerated temporarily during contact
    changeover or breaker movement. If the condition persists for the
    configured delay, it becomes a feedback fault.
-------------------------------------------------------------------------------------*)
    tonFeedbackFaultDelay(
        IN := xOpenFeedbackDebounced = xCloseFeedbackDebounced,
        PT := tFeedbackFaultDelay
    );
{endregion}


{region 'Command Timers'}
    tonOpenPulse(
        IN := eCurrentState = MVBreakerState#OPENING,
        PT := tOpenPulse
    );
    tonOpenTimeout(
        IN := eCurrentState = MVBreakerState#OPENING,
        PT := tOpenTimeout
    );
    tonClosePulse(
        IN := eCurrentState = MVBreakerState#CLOSING,
        PT := tClosePulse
    );
    tonCloseTimeout(
        IN := eCurrentState = MVBreakerState#CLOSING,
        PT := tCloseTimeout
    );
{endregion}

(*===================================================================================
                                    Process Inputs
=====================================================================================*)
{region 'Operating Mode'}
(*-----------------------------------------------------------------------------------
                            OPERATING MODE SELECTION
                0:  INVALID
                1:  AUTO
                2:  MANUAL
                3:  TEST
                4:  MAINTENANCE
                5:  DISABLED
-------------------------------------------------------------------------------------*)
    IF NOT xEnable THEN
        eOperatingMode := MVBreakerMode#DISABLED;
    ELSIF MVBreaker.DI.xMaintenance THEN
        eOperatingMode := MVBreakerMode#MAINTENANCE;
    ELSE
        CASE uiModeRequest OF
    
            1:
                eOperatingMode := MVBreakerMode#AUTO;
            2:
                eOperatingMode := MVBreakerMode#MANUAL;
            3:
                eOperatingMode := MVBreakerMode#TEST;
            4:
                eOperatingMode := MVBreakerMode#MAINTENANCE;
            5:
                eOperatingMode := MVBreakerMode#DISABLED;
            ELSE
                eOperatingMode := MVBreakerMode#INVALID;
        END_CASE;
    END_IF;
{endregion}

{region 'Control Authority'}
(*-----------------------------------------------------------------------------------
                        PLC CONTROL AUTHORITY
    The PLC must have breaker-control authority in Auto, Manual and Test.
    Maintenance and Disabled operation remain outside PLC control.
-------------------------------------------------------------------------------------*)
    CASE eOperatingMode OF

        MVBreakerMode#AUTO,
        MVBreakerMode#MANUAL,
        MVBreakerMode#TEST:

            xControlAllowed := xPLCControlAuthority;

        ELSE

            xControlAllowed := FALSE;

    END_CASE;
{endregion}

{region 'Request Source Selection'}
(*-----------------------------------------------------------------------------------
    Auto uses plant requests.
    Manual and Test use HMI requests.

    Both request edges are passed to the FSM. The confirmed breaker state
    determines which direction is meaningful; the other request is discarded.
-------------------------------------------------------------------------------------*)
    CASE eOperatingMode OF

        MVBreakerMode#AUTO:

            xOpenRequestPulse  := rtAutoOpenRequest.Q;
            xCloseRequestPulse := rtAutoCloseRequest.Q;


        MVBreakerMode#MANUAL,
        MVBreakerMode#TEST:

            xOpenRequestPulse  := rtHMIOpenRequest.Q;
            xCloseRequestPulse := rtHMICloseRequest.Q;

    END_CASE;
{endregion}

{region 'Derive Basic Statuses'}
(*-----------------------------------------------------------------------------------
                                Set Statusses
-------------------------------------------------------------------------------------*)
    MVBreaker.Status.xOpen                  :=  xOpenFeedbackDebounced
                                                AND NOT xCloseFeedbackDebounced;

    MVBreaker.Status.xClosed                :=  xCloseFeedbackDebounced
                                                AND NOT xOpenFeedbackDebounced;

    MVBreaker.Status.xTripped               :=  MVBreaker.DI.xTripped;

    MVBreaker.Status.xPLCControlAuthority   :=  xPLCControlAuthority;

    MVBreaker.Status.xCommandBusy           :=  (eCurrentState = MVBreakerState#OPENING)
                                                OR (eCurrentState = MVBreakerState#CLOSING)
                                                OR (eCurrentState = MVBreakerState#RETRY_WAIT);

    MVBreaker.Status.xRetryPending          :=  eCurrentState = MVBreakerState#RETRY_WAIT;

{endregion}

{region 'Calculate Faults'}
(*-----------------------------------------------------------------------------------
                            Calculate Faults
-------------------------------------------------------------------------------------*)
    MVBreaker.Faults.xFeedbackFault             :=  tonFeedbackFaultDelay.Q;

    MVBreaker.Faults.xEarthedWhileClosed        :=  MVBreaker.DI.xEarthed
                                                AND MVBreaker.Status.xClosed;

    MVBreaker.Faults.xIsolatorOpenWhileClosed   :=  MVBreaker.DI.xIsolatorOpen
                                                AND MVBreaker.Status.xClosed;

    MVBreaker.Faults.xControlSupplyFault        :=  MVBreaker.DI.xMotorSupplyTripped
                                                OR  MVBreaker.DI.xOpenCoilSupplyTripped
                                                OR  MVBreaker.DI.xCloseCoilSupplyTripped;

    MVBreaker.Faults.xProtectionFault           :=  NOT MVBreaker.DI.xProtectionHealthy
                                                OR  MVBreaker.DI.xProtectionCommonAlarm;

    MVBreaker.Faults.xFault                     :=  MVBreaker.Faults.xFeedbackFault
                                                OR  MVBreaker.Faults.xEarthedWhileClosed
                                                OR  MVBreaker.Faults.xIsolatorOpenWhileClosed
                                                OR  MVBreaker.Faults.xControlSupplyFault
                                                OR  MVBreaker.Faults.xProtectionFault;
    
{endregion}

{region 'Operating Permissions'}
(*-----------------------------------------------------------------------------------
    Any active breaker fault prevents both opening and closing.

    xReadyToClose represents the breaker's physical readiness only.
    xCanOpen and xCanClose include mode, authority, external permission,
    stable FSM state and the minimum command gap.
-------------------------------------------------------------------------------------*)
    MVBreaker.Status.xAutoControlActive :=      (eOperatingMode = MVBreakerMode#AUTO)
                                        AND     xControlAllowed;
                                        
    MVBreaker.Status.xReadyToClose      :=      MVBreaker.Status.xOpen
                                        AND     MVBreaker.DI.xSpringCharged
                                        AND     NOT MVBreaker.Status.xTripped
                                        AND     NOT MVBreaker.DI.xEarthed
                                        AND     NOT MVBreaker.DI.xIsolatorOpen
                                        AND     NOT MVBreaker.Faults.xFault;

    MVBreaker.Status.xCanOpen          :=       xControlAllowed
                                        AND     NOT MVBreaker.Faults.xFault
                                        AND     NOT MVBreaker.Status.xTripped
                                        AND     (eCurrentState = MVBreakerState#CLOSED)
                                        AND     MVBreaker.Status.xClosed
                                        AND     MVBreaker.Interlocks.xExternalOpenPermit;

    MVBreaker.Status.xCanClose         :=       xControlAllowed
                                        AND     NOT MVBreaker.Faults.xFault
                                        AND     (eCurrentState = MVBreakerState#OPEN)
                                        AND     MVBreaker.Status.xReadyToClose
                                        AND     MVBreaker.Interlocks.xExternalClosePermit;
{endregion}


{region 'Acknowledge Alarms'}
    IF rtHMIAlarmAcknowledge.Q THEN
        MVBreaker.Alarms.xFailToOpen  := FALSE;
        MVBreaker.Alarms.xFailToClose := FALSE;
    END_IF;
{endregion}

(*===================================================================================
                                MV BREAKER FSM
=====================================================================================*)


{region 'FSM'}
(*-----------------------------------------------------------------------------------
                                FSM opperation
-------------------------------------------------------------------------------------*)
    IF NOT xEnable THEN
        eNextState                      := MVBreakerState#UNKNOWN;
        MVBreaker.Status.uiRetriesUsed  := 0;
    ELSIF MVBreaker.DI.xTripped THEN
        eNextState                      := MVBreakerState#TRIPPED;
    ELSIF MVBreaker.Faults.xFault THEN
        eNextState                      := MVBreakerState#FAULT;
    ELSE
    
        CASE eCurrentState OF
    
            MVBreakerState#UNKNOWN:
            
                    IF MVBreaker.Status.xOpen THEN
                        eNextState := MVBreakerState#OPEN;
                    ELSIF MVBreaker.Status.xClosed THEN
                        eNextState := MVBreakerState#CLOSED;
                    END_IF;
    
            MVBreakerState#OPEN:
            
                    IF xControlAllowed THEN
                        
                        IF xCloseRequestPulse AND MVBreaker.Status.xCanClose THEN
                            MVBreaker.Status.uiRetriesUsed  := 0;
                            eRetryTargetState               := MVBreakerState#CLOSING;
                            eNextState                      := MVBreakerState#CLOSING;
                        ELSIF NOT MVBreaker.Status.xOpen THEN
                            eNextState                      := MVBreakerState#UNKNOWN;
                        END_IF;  
                        
                    ELSIF NOT MVBreaker.Status.xOpen THEN
                        //Breaker isnt Open Anymore
                        eNextState := MVBreakerState#UNKNOWN;
                    END_IF;

            MVBreakerState#CLOSED:
    
                    IF xControlAllowed THEN
                        
                        IF xOpenRequestPulse AND MVBreaker.Status.xCanOpen THEN
                            MVBreaker.Status.uiRetriesUsed := 0;
                            eRetryTargetState              := MVBreakerState#OPENING;
                            eNextState                     := MVBreakerState#OPENING;
                        ELSIF NOT MVBreaker.Status.xClosed THEN
                            eNextState                      := MVBreakerState#UNKNOWN;
                        END_IF;  
                        
                    ELSIF NOT MVBreaker.Status.xClosed THEN
                        //Breaker isnt Closed Anymore
                        eNextState := MVBreakerState#UNKNOWN;
                    END_IF;
    
            MVBreakerState#TRIPPED:
            
                    IF MVBreaker.Status.xOpen THEN
                        eNextState := MVBreakerState#OPEN;
                    ELSIF MVBreaker.Status.xClosed THEN
                        eNextState := MVBreakerState#CLOSED;
                    ELSE
                        // Trip cleared, but no stable position is confirmed
                        eNextState := MVBreakerState#UNKNOWN;
                    END_IF;
    
            MVBreakerState#OPENING:
            
                    IF xControlAllowed THEN
                        
                        IF MVBreaker.Status.xOpen THEN
                            // Opening completed
                            eNextState := MVBreakerState#OPEN;
                        ELSIF NOT MVBreaker.Interlocks.xExternalOpenPermit OR MVBreaker.DI.xOpenCoilSupplyTripped THEN
                            // Opening is no longer allowed
                            eNextState := MVBreakerState#UNKNOWN;
                        ELSE
                            //Check timeout
                            IF tonOpenTimeout.Q THEN
                                
                                    //check retries only from a known, safe starting position
                                    IF MVBreaker.Status.uiRetriesUsed < uiMaxRetries AND MVBreaker.Status.xClosed THEN
                                            MVBreaker.Status.uiRetriesUsed  := MVBreaker.Status.uiRetriesUsed + 1;
                                            eNextState                      := MVBreakerState#RETRY_WAIT;
                                    ELSE
                                            MVBreaker.Alarms.xFailToOpen    := TRUE;
                                            eNextState                      := MVBreakerState#UNKNOWN;
                                    END_IF;
                                    
                            ELSE
                                MVBreaker.DQ.xCmdOpen := NOT tonOpenPulse.Q;
                            END_IF;
                           
                        END_IF;
                        
                    ELSE
                        //PLC Has NO CONTROL
                        eNextState := MVBreakerState#UNKNOWN;
                    END_IF;
    
            MVBreakerState#CLOSING:
            
                    IF xControlAllowed THEN
                        
                        IF MVBreaker.Status.xClosed THEN
                            // Closing completed
                            eNextState := MVBreakerState#Closed;
                        ELSIF NOT MVBreaker.Interlocks.xExternalClosePermit THEN
                            // Closing is no longer allowed
                            eNextState := MVBreakerState#UNKNOWN;
                        ELSIF MVBreaker.Faults.xControlSupplyFault THEN
                            //Fault occured with Control Supply
                            eNextState := MVBreakerState#UNKNOWN;
                        ELSE
                            //Check timeout
                            IF tonCloseTimeout.Q THEN
                                
                                    //check retries only from a known, safe starting position
                                    IF MVBreaker.Status.uiRetriesUsed < uiMaxRetries AND MVBreaker.Status.xOpen THEN
                                            MVBreaker.Status.uiRetriesUsed  := MVBreaker.Status.uiRetriesUsed + 1;
                                            eNextState                      := MVBreakerState#RETRY_WAIT;
                                    ELSE
                                            MVBreaker.Alarms.xFailToClose   := TRUE;
                                            eNextState                      := MVBreakerState#UNKNOWN;
                                    END_IF;
                                    
                            ELSE
                                MVBreaker.DQ.xCmdClose := NOT tonClosePulse.Q;
                            END_IF;
                           
                        END_IF;
                        
                    ELSE
                        //PLC Has NO CONTROL
                        eNextState := MVBreakerState#UNKNOWN;
                    END_IF;       
    
            MVBreakerState#RETRY_WAIT:
            
                    IF NOT xControlAllowed THEN
                            eNextState := MVBreakerState#UNKNOWN;
                    ELSIF eRetryTargetState = MVBreakerState#OPENING THEN
                    
                            IF MVBreaker.Status.xClosed THEN
                                eNextState := MVBreakerState#OPENING;
                            ELSE
                                eNextState := MVBreakerState#UNKNOWN;
                            END_IF;
                    
                    ELSIF eRetryTargetState = MVBreakerState#CLOSING THEN
                    
                            IF MVBreaker.Status.xReadyToClose THEN
                                eNextState := MVBreakerState#CLOSING;
                            ELSE
                                eNextState := MVBreakerState#UNKNOWN;
                            END_IF;
                    
                    ELSE
                            eNextState := MVBreakerState#INVALID;
                    END_IF;
    
            MVBreakerState#FAULT:

                    IF xControlAllowed THEN
                        
                        IF rtHMIResetRequest.Q AND NOT MVBreaker.Faults.xFault THEN           
                                eNextState := MVBreakerState#UNKNOWN;        
                        END_IF;
                        
                    ELSE
                        // Observer mode automatically recovers when the fault clears
                        IF NOT MVBreaker.Faults.xFault THEN
                            eNextState := MVBreakerState#UNKNOWN;
                        END_IF;
                        
                    END_IF;
    
            MVBreakerState#INVALID:
                    IF xOpenFeedbackDebounced AND NOT xCloseFeedbackDebounced THEN
                
                        eNextState := MVBreakerState#OPEN;
                
                    ELSIF xCloseFeedbackDebounced AND NOT xOpenFeedbackDebounced THEN
                
                        eNextState := MVBreakerState#CLOSED;
                
                    ELSIF NOT xOpenFeedbackDebounced AND NOT xCloseFeedbackDebounced THEN
                
                        eNextState := MVBreakerState#UNKNOWN;
                
                    END_IF;
    
    
            ELSE
                eNextState := MVBreakerState#INVALID;
        END_CASE;
    END_IF;
{endregion}

(*===================================================================================
                                    Set Outputs
=====================================================================================*)

{region 'Publish Operating Mode'}
(*-----------------------------------------------------------------------------------
                                Mode Control
-------------------------------------------------------------------------------------*)
    MVBreaker.OperatingMode := eOperatingMode;

    CASE eOperatingMode OF

        MVBreakerMode#INVALID:
            MVBreaker.uiOperatingMode := UINT#0;
        MVBreakerMode#AUTO:
            MVBreaker.uiOperatingMode := UINT#1;
        MVBreakerMode#MANUAL:
            MVBreaker.uiOperatingMode := UINT#2;
        MVBreakerMode#TEST:
            MVBreaker.uiOperatingMode := UINT#3;
        MVBreakerMode#MAINTENANCE:
            MVBreaker.uiOperatingMode := UINT#4;
        MVBreakerMode#DISABLED:
            MVBreaker.uiOperatingMode := UINT#5;
        ELSE
            MVBreaker.uiOperatingMode := UINT#0;

    END_CASE;
{endregion}


{region 'Publish Current State'}
(*-----------------------------------------------------------------------------------
                                State Control
-------------------------------------------------------------------------------------*)
    MVBreaker.State := eCurrentState;

    CASE eCurrentState OF

        MVBreakerState#UNKNOWN:
            MVBreaker.uiState := UINT#0;
        MVBreakerState#OPEN:
            MVBreaker.uiState := UINT#1;
        MVBreakerState#CLOSED:
            MVBreaker.uiState := UINT#2;
        MVBreakerState#TRIPPED:
            MVBreaker.uiState := UINT#3;
        MVBreakerState#OPENING:
            MVBreaker.uiState := UINT#4;
        MVBreakerState#CLOSING:
            MVBreaker.uiState := UINT#5;
        MVBreakerState#RETRY_WAIT:
            MVBreaker.uiState := UINT#6;
        MVBreakerState#FAULT:
            MVBreaker.uiState := UINT#7;
        MVBreakerState#INVALID:
            MVBreaker.uiState := UINT#8;

        ELSE
            MVBreaker.uiState := UINT#8;

    END_CASE;
{endregion}


{region 'Publish Alarms'}
(*-----------------------------------------------------------------------------------
    Command-failure alarms are latched until acknowledged.
-------------------------------------------------------------------------------------*)
    MVBreaker.Alarms.xAlarm :=
        MVBreaker.Alarms.xFailToOpen
        OR MVBreaker.Alarms.xFailToClose
        OR MVBreaker.Faults.xFault
        OR MVBreaker.Status.xTripped
        OR (eCurrentState = MVBreakerState#FAULT);
{endregion}


{region 'Publish Control Owner'}
(*-----------------------------------------------------------------------------------
                            CONTROL OWNER
                0 = UNKNOWN
                1 = PLC
                2 = DSE
                3 = LOCAL
-------------------------------------------------------------------------------------*)
    CASE eOperatingMode OF

        MVBreakerMode#MAINTENANCE:

            MVBreaker.uiControlOwner := UINT#3;

        MVBreakerMode#AUTO,
        MVBreakerMode#MANUAL,
        MVBreakerMode#TEST:

            IF xPLCControlAuthority THEN
                MVBreaker.uiControlOwner := UINT#1;
            ELSE
                MVBreaker.uiControlOwner := UINT#2;
            END_IF;

        ELSE

            MVBreaker.uiControlOwner := UINT#0;

    END_CASE;
{endregion}
